  "Aicontexttype:object_layout_fields__sys": "RECREATE Aicontexttype object_layout_fields__sys (\n   label('Object Layout Fields'),\n   active(true),\n   admin_configurable(false),\n   configuration_code('Aicontexttypeconfigurationcode.com.veeva.vault.system.context.DynamicObjectLayoutFieldsConfigurationContextType'),\n   configuration_layout(),\n   runtime_code('Aicontexttyperuntimecode.com.veeva.vault.system.context.DynamicObjectLayoutFieldsRuntimeContextType')\n   );",
