  "Dashboard:glossary_overview__c": "RECREATE Dashboard glossary_overview__c (\n   active(true),\n   label('Glossary Overview'),\n   description('Glossary Overview'),\n   editors(),\n   viewers(),\n   owners('User.michael.ferrell@veeva.com'),\n   dashboard_markup({<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<vault:dashboard xmlns:vault=\"VeevaVault\" type=\"Two-Columns\">\n  <vault:chart name=\"glossary_use_by_user__c\" label=\"% Glossary Use by User\" type=\"pie\" featured=\"false\" report=\"Report.glossary_use_by_user__c\">\n    <vault:format showcategory=\"false\" showpercentage=\"true\" showlegend=\"true\" />\n    <vault:series metric=\"RecordCount\">\n      <vault:grouping key=\"glossary_event__sys.performed_by_user__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"of_external_searches__c\" label=\"# of External Searches\" type=\"number\" featured=\"false\" report=\"Report.external_glossary_searches__c\">\n    <vault:format showmetrics=\"true\" showgroupings=\"true\" showpercentage=\"false\">\n      <vault:range color=\"#427B2E\" min=\"0.0\" max=\"30.0\" />\n      <vault:range color=\"#D9780D\" min=\"31.0\" max=\"70.0\" />\n      <vault:range color=\"#B71307\" min=\"71.0\" max=\"100.0\" />\n    </vault:format>\n    <vault:series metric=\"RecordCount\" unitlabel=\"            \">\n      <vault:grouping key=\"glossary_event__sys.glossary_definition_match_type__sys\" value=\"AllValues\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"definitions_by_state__c\" label=\"Definitions by State\" type=\"pie\" featured=\"false\" report=\"Report.glossary_dashboard_definitions_by_lif__c\">\n    <vault:format showcategory=\"true\" showpercentage=\"true\" showlegend=\"true\" />\n    <vault:series metric=\"RecordCount\">\n      <vault:grouping key=\"glossary_definition__sys.state__v\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"definitions_in_review__c\" label=\"Definition(s) &quot;In Review&quot;\" type=\"number\" featured=\"false\" report=\"Report.glossary_dashboard_definitions_by_lif__c\">\n    <vault:format showmetrics=\"false\" showgroupings=\"false\" showpercentage=\"true\">\n      <vault:range color=\"#427B2E\" min=\"0.0\" max=\"30.0\" />\n      <vault:range color=\"#D9780D\" min=\"31.0\" max=\"70.0\" />\n      <vault:range color=\"#B71307\" min=\"71.0\" max=\"100.0\" />\n    </vault:format>\n    <vault:series metric=\"RecordCount\" unitlabel=\"                 \">\n      <vault:grouping key=\"glossary_definition__sys.state__v\" value=\"In Review\" labelvalues=\"In Review\" labelLanguage=\"en\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"withdrawn_definitions__c\" label=\"&quot;Withdrawn&quot; Definition(s)\" type=\"number\" featured=\"false\" report=\"Report.glossary_dashboard_definitions_by_lif__c\">\n    <vault:format showmetrics=\"false\" showgroupings=\"false\" showpercentage=\"true\">\n      <vault:range color=\"#427B2E\" min=\"0.0\" max=\"30.0\" />\n      <vault:range color=\"#D9780D\" min=\"31.0\" max=\"70.0\" />\n      <vault:range color=\"#B71307\" min=\"71.0\" max=\"100.0\" />\n    </vault:format>\n    <vault:series metric=\"RecordCount\" unitlabel=\"                 \">\n      <vault:grouping key=\"glossary_definition__sys.state__v\" value=\"Withdrawn\" labelvalues=\"Withdrawn\" labelLanguage=\"en\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"terms_without_translations__c\" label=\"Terms without Translations\" type=\"number\" featured=\"false\" report=\"Report.terms_without_translations__c\">\n    <vault:format showmetrics=\"true\" showgroupings=\"true\" showpercentage=\"false\">\n      <vault:range color=\"#427B2E\" min=\"0.0\" max=\"20.0\" />\n      <vault:range color=\"#D9780D\" min=\"21.0\" max=\"40.0\" />\n      <vault:range color=\"#B71307\" min=\"41.0\" max=\"100.0\" />\n    </vault:format>\n    <vault:series metric=\"RecordCount\" unitlabel=\"    \">\n      <vault:grouping key=\"english_definitions__c.glossary_definition__sys.name__v\" value=\"AllValues\" />\n      <vault:grouping key=\"join_ref_1__v.glossary_definition__sys.glossary_definition_language__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"searches_without_definitions2__c\" label=\"Searches without Definitions\" type=\"number\" featured=\"false\" report=\"Report.unmatched_terms__c\">\n    <vault:format showmetrics=\"true\" showgroupings=\"true\" showpercentage=\"false\">\n      <vault:range color=\"#427B2E\" min=\"0.0\" max=\"20.0\" />\n      <vault:range color=\"#D9780D\" min=\"21.0\" max=\"40.0\" />\n      <vault:range color=\"#B71307\" min=\"41.0\" max=\"100.0\" />\n    </vault:format>\n    <vault:series metric=\"RecordCount\" unitlabel=\"        \">\n      <vault:grouping key=\"glossary_event__sys.glossary_event_search_phrase__sys\" value=\"AllValues\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"of_definitions_copied1__c\" label=\"% of Definitions Copied\" type=\"pie\" featured=\"false\" report=\"Report.of_copied_definitions__c\">\n    <vault:format showcategory=\"false\" showpercentage=\"true\" showlegend=\"true\" />\n    <vault:series metric=\"RecordCount\">\n      <vault:grouping key=\"glossary_event__sys.glossary_event_definition_copied__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"glossary_use_by_term__c\" label=\"Glossary Use by Term\" type=\"pareto\" featured=\"false\" report=\"Report.glossary_use_by_term__c\">\n    <vault:format showlegend=\"true\" showvalue=\"true\" xaxislabel=\"Glossary Term\" yaxislabel=\"Record Count (Glossary Event)\" />\n    <vault:series metric=\"RecordCount\">\n      <vault:grouping key=\"glossary_event__sys.glossary_definition_term__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"definitions_by_language__c\" label=\"Definitions by Language\" type=\"pareto\" featured=\"false\" report=\"Report.glossary_dashboard_definitions_by_lan__c\">\n    <vault:format showlegend=\"true\" showvalue=\"true\" xaxislabel=\"Language\" yaxislabel=\"Record Count (Definition)\" />\n    <vault:series metric=\"RecordCount\">\n      <vault:grouping key=\"glossary_definition__sys.glossary_definition_language__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:chart name=\"terms_with_translations__c\" label=\"Terms with Translations\" type=\"bar\" featured=\"false\" report=\"Report.glossary_translations__c\">\n    <vault:format showlegend=\"true\" showvalue=\"false\" xaxislabel=\"Language\" yaxislabel=\"Glossary Definition Count\" stacking=\"percent\" />\n    <vault:series metric=\"join_ref_1__v.glossary_definition__sys.object_count__v\">\n      <vault:grouping key=\"english_definitions__c.glossary_definition__sys.glossary_definition_language__sys\" value=\"\" />\n      <vault:grouping key=\"join_ref_1__v.glossary_definition__sys.glossary_definition_language__sys\" value=\"\" />\n    </vault:series>\n  </vault:chart>\n  <vault:spacer />\n</vault:dashboard>\n}),\n   tags()\n);",
