  "Notificationtemplate:basebasereviewedwithchanges__c": "RECREATE Notificationtemplate basebasereviewedwithchanges__c (\n   label('BASE-baseReviewedWithChanges'),\n   active(true),\n   description(),\n   email_preferences('every_occurrence__sys'),\n   referenced_component(),\n   subject('Notification: \"${docNameNoLink}\" review completed, changes required'),\n   notification('Review of <b>${docName}</b> has been completed. Changes are required. Comments have been captured as annotations on the document.'),\n   email_body('<p>${notificationMessage}</p>'),\n   entity_type('document'),\n   notification_category('none__sys')\n);",
