  "Notificationtemplate:basereviewcompletereview__c": "RECREATE Notificationtemplate basereviewcompletereview__c (\n   label('BASE-Review-CompleteReview'),\n   active(true),\n   description(),\n   email_preferences('every_occurrence__sys'),\n   referenced_component(),\n   subject('New Task: Assess Review Outcome for \"${docNameNoLink}\"'),\n   notification('Please review all comments for <b>${docName}</b> and determine if it is ready for formal approval, or if significant changes are required and it should be returned to the owner. All comments can be viewed from the document information page.'),\n   email_body('You have been assigned a task for <b>${docName}</b>. ${notificationMessage}</p> Due date: ${taskDueDate}<br> Document owner: ${docOwnerName}<br> Workflow owner: ${workflowInitiatorName}<br> '),\n   entity_type('document'),\n   notification_category('tasks__sys')\n);",
  "Notificationtemplate:basereviewedapproved__v": "RECREATE Notificationtemplate basereviewedapproved__v (\n   label('BASE-ReviewedApproved'),\n   active(true),\n   description(),\n   email_preferences('summary__sys'),\n   referenced_component('Object.envelope__sys'),\n   subject('Notification: Review completed, changes not required'),\n   notification('Review of Documents <b>${multiDocDocumentsList}</b> have been completed. Changes are not required. The Owner will start the approval process.'),\n   email_body('<p>${notificationMessage}</p>'),\n   entity_type('object'),\n   notification_category('outcomes__c')\n);",
