  "Notificationtemplate:ml_model_testing_failure__sys": "RECREATE Notificationtemplate ml_model_testing_failure__sys (\n   label('Model Testing Failure'),\n   active(true),\n   description(),\n   email_preferences('every_occurrence__sys'),\n   referenced_component('Object.trained_model__sys'),\n   subject('Model Testing for the Trained Model \"${Object.name__v}\" has failed.'),\n   notification('<p>Model Testing for the Trained Model \"${Object.name__v}\" has failed for the following reason:</p><p>${Custom.mlFailureReason}</p>'),\n   email_body('<p>${notificationMessage}</p> <p>Please <a href=\"${uiBaseExtUrl}\">login to Vault</a> to view all of your tasks and notifications.</p>'),\n   entity_type('object'),\n   notification_category('none__sys')\n);",
