  "Notificationtemplate:vault_config_report_error__v": "RECREATE Notificationtemplate vault_config_report_error__v (\n   label('Configuration Report Error'),\n   active(true),\n   description('Configuration Report Job Notification error template'),\n   email_preferences('every_occurrence__sys'),\n   referenced_component(),\n   subject('Your Vault Configuration Report has failed'),\n   notification('\n   <p>Your Vault Configuration Report has failed </p>\n   <p>Details: </p>\n   <ul>\n        <li>Reason for failure: ${failureMessage} </li>\n        <li>Include Vault Settings: ${includeVaultSettings} </li>\n        <li>Include Document & Binder Templates: ${includeDocumentBinderTemplates} </li>\n        <li>Include Inactive Components: ${includeInactiveComponents} </li>\n        <li>Suppress Empty Results: ${suppressEmptyResults} </li>\n        <li>Include Components Modified Since: ${includeComponentsModifiedSince} </li>\n        <li>Output Format: ${outputFormat} </li>\n        <li>Start Time: ${startTime} </li>\n        <li>Duration: ${duration} </li>\n   </ul>\n   '),\n   email_body('\n   <p>Your Vault Configuration Report has failed </p>\n   <p>Details: </p>\n   <ul>\n        <li>Reason for failure: ${failureMessage} </li>\n        <li>Include Vault Settings: ${includeVaultSettings} </li>\n        <li>Include Document & Binder Templates: ${includeDocumentBinderTemplates} </li>\n        <li>Include Inactive Components: ${includeInactiveComponents} </li>\n        <li>Suppress Empty Results: ${suppressEmptyResults} </li>\n        <li>Include Components Modified Since: ${includeComponentsModifiedSince} </li>\n        <li>Output Format: ${outputFormat} </li>\n        <li>Start Time: ${startTime} </li>\n        <li>Duration: ${duration} </li>\n   </ul>\n   '),\n   entity_type('document'),\n   notification_category('none__sys')\n);",
